CREATE TABLE public.tax_impact_volume_imports (id uuid PRIMARY KEY, analysis_id uuid NOT NULL, client_tenant_id uuid NOT NULL, filename text NOT NULL, storage_path text NOT NULL UNIQUE, file_hash text NOT NULL, sheet text NOT NULL, mapping jsonb NOT NULL, rows jsonb NOT NULL, errors jsonb NOT NULL DEFAULT '[]', created_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(analysis_id,client_tenant_id) REFERENCES public.tax_impact_analyses(id,client_tenant_id), CHECK(storage_path=client_tenant_id::text || '/' || analysis_id::text || '/volume-' || id::text || CASE WHEN lower(filename) LIKE '%.csv' THEN '.csv' ELSE '.xlsx' END));
GRANT SELECT,INSERT ON public.tax_impact_volume_imports TO authenticated;
GRANT ALL ON public.tax_impact_volume_imports TO service_role;
ALTER TABLE public.tax_impact_volume_imports ENABLE ROW LEVEL SECURITY;
CREATE POLICY tic_volume_read ON public.tax_impact_volume_imports FOR SELECT TO authenticated USING(public.tax_impact_access(client_tenant_id));
CREATE POLICY tic_volume_insert ON public.tax_impact_volume_imports FOR INSERT TO authenticated WITH CHECK(public.tax_impact_access(client_tenant_id) AND created_by=auth.uid());
CREATE TABLE public.tax_impact_scenarios (analysis_id uuid PRIMARY KEY, client_tenant_id uuid NOT NULL, parameters jsonb NOT NULL DEFAULT '{}', updated_by uuid NOT NULL DEFAULT auth.uid(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(analysis_id,client_tenant_id) REFERENCES public.tax_impact_analyses(id,client_tenant_id));
GRANT SELECT,INSERT,UPDATE ON public.tax_impact_scenarios TO authenticated;
GRANT ALL ON public.tax_impact_scenarios TO service_role;
ALTER TABLE public.tax_impact_scenarios ENABLE ROW LEVEL SECURITY;
CREATE POLICY tic_scenario_read ON public.tax_impact_scenarios FOR SELECT TO authenticated USING(public.tax_impact_access(client_tenant_id));
CREATE POLICY tic_scenario_insert ON public.tax_impact_scenarios FOR INSERT TO authenticated WITH CHECK(public.tax_impact_access(client_tenant_id) AND updated_by=auth.uid());
CREATE POLICY tic_scenario_update ON public.tax_impact_scenarios FOR UPDATE TO authenticated USING(public.tax_impact_access(client_tenant_id)) WITH CHECK(public.tax_impact_access(client_tenant_id) AND updated_by=auth.uid());
CREATE TABLE public.tax_impact_source_checks (client_tenant_id uuid NOT NULL REFERENCES public.tenants(id), day date NOT NULL, state text NOT NULL DEFAULT 'checking' CHECK(state IN ('checking','checked','failed')), claim_token uuid NOT NULL DEFAULT gen_random_uuid(), lease_until timestamptz NOT NULL DEFAULT now()+interval '60 seconds', result jsonb NOT NULL DEFAULT '{}', checked_at timestamptz, PRIMARY KEY(client_tenant_id,day));
GRANT SELECT,INSERT,UPDATE ON public.tax_impact_source_checks TO authenticated;
GRANT ALL ON public.tax_impact_source_checks TO service_role;
ALTER TABLE public.tax_impact_source_checks ENABLE ROW LEVEL SECURITY;
CREATE POLICY tic_source_read ON public.tax_impact_source_checks FOR SELECT TO authenticated USING(public.tax_impact_access(client_tenant_id));
CREATE POLICY tic_source_insert ON public.tax_impact_source_checks FOR INSERT TO authenticated WITH CHECK(public.tax_impact_access(client_tenant_id));
CREATE POLICY tic_source_update ON public.tax_impact_source_checks FOR UPDATE TO authenticated USING(public.tax_impact_access(client_tenant_id)) WITH CHECK(public.tax_impact_access(client_tenant_id));
CREATE FUNCTION public.claim_tax_impact_source_check(_tenant_id uuid,_day date) RETURNS SETOF public.tax_impact_source_checks LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ INSERT INTO public.tax_impact_source_checks(client_tenant_id,day) VALUES(_tenant_id,_day) ON CONFLICT(client_tenant_id,day) DO UPDATE SET claim_token=gen_random_uuid(),lease_until=now()+interval '60 seconds',state='checking' WHERE tax_impact_source_checks.state='checking' AND tax_impact_source_checks.lease_until<now() RETURNING * $$;
REVOKE ALL ON FUNCTION public.claim_tax_impact_source_check(uuid,date) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.claim_tax_impact_source_check(uuid,date) TO authenticated;
CREATE POLICY tic_volume_original_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='tax-impact-originals' AND lower(storage.extension(storage.objects.name)) IN ('xlsx','csv') AND (storage.filename(storage.objects.name)) LIKE 'volume-%' AND EXISTS(SELECT 1 FROM public.tax_impact_analyses a WHERE a.client_tenant_id::text=(storage.foldername(storage.objects.name))[1] AND a.id::text=(storage.foldername(storage.objects.name))[2] AND public.tax_impact_access(a.client_tenant_id)));
CREATE INDEX tic_volume_analysis ON public.tax_impact_volume_imports(analysis_id,created_at DESC);